const FEATURE_KEYS = [
  { emoji: "🧠", k: "f1" },
  { emoji: "🌐", k: "f2" },
  { emoji: "🎯", k: "f3" },
  { emoji: "⏱️", k: "f4" },
  { emoji: "📊", k: "f5" },
  { emoji: "🔒", k: "f6" },
] as const;

function feats(t: Record<string, { title: string; body: string }>): FeatureItem[] {
  return FEATURE_KEYS.map((f) => ({ emoji: f.emoji, title: t[f.k].title, body: t[f.k].body }));
}

