const DICT: Record<Locale, Translations> = Object.fromEntries(
  LOCALES.map((l) => [l, {
    ...({ en, ar, fr, es, de, it, pt, tr, ur, fa } as Record<Locale, Omit<Translations, keyof Extras | "account" | "homeExtra" | "checkout" | "library" | "community" | "credits">>)[l],
    ...EXTRAS[l],
    account: ACCOUNTS[l],
    homeExtra: HOME_EXTRAS[l],
    checkout: CHECKOUTS[l],
    library: LIBRARIES[l],
    community: COMMUNITIES[l],
    credits: CREDITS[l],
  }])
) as Record<Locale, Translations>;

export function getTranslations(locale: Locale): Translations {
  return DICT[locale] ?? DICT.en;
}
